mapper.select:
select 
from biz_stock_snapshot s


        and s.snapshot_date = #{snapshotDate}


        and s.snapshot_date >= #{params.beginSnapshotDate}


        and s.snapshot_date <= #{params.endSnapshotDate}


        and s.create_time >= #{params.beginTime}


        and s.create_time <= #{params.endTime}


order by s.snapshot_date desc, s.snapshot_id desc
